
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_k_meyer_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_k_meyer", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([9.394127313515020e+01, 9.028797857304512e+01, 8.529296928150342e+01, 7.861307467775090e+01, 6.995877107648748e+01, 5.924265953533062e+01, 4.680027839693433e+01, 3.360904334789883e+01, 2.129736658648859e+01, 1.163260320343326e+01, 5.379203467403580e+00, 2.539282399699592e+00, 1.906712656009077e+00, 1.265030996009430e+00, 6.472633683708641e-01, 2.718408608707463e-01, 1.849937792049677e-01, 5.118704532525428e-01, 5.975526112839292e-01, 5.742747819348331e-01]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


